// myle.IdempotencyKey).
//
// It answers a *Paginator over a single page (the result per recipient). Nothing is sent until you iterate.
//
// Errors worth handling (errors.As):
//
//   - *CoreModuleRequiredError (402 core.module-required): The organization's plan or settings lack the module this
//     operation belongs to.
//   - *CoreSubscriptionRequiredError (402 core.subscription-required): The organization has no active paid
//     subscription: it is read-only, it can read and export but not write.
//   - *CorePlanLimitReachedError (402 core.plan-limit-reached): The organization's plan allows no more of what this
//     operation creates.
//   - *AuthRightMissingError (403 auth.right.missing): The caller lacks the right this operation requires in this
//     organization.
//   - *CoreNotFoundError (404 core.not-found): What the path names does not exist, or the caller cannot see it (the
//     same answer for both).
//   - *CoreValidationFailedError (422 core.validation-failed): Fields of the request are invalid.
//   - *CoreIdempotencyKeyReusedError (422 core.idempotency-key-reused): This Idempotency-Key was already used for a
//     request with another body.
//
// Example:
//
//	org := client.Organization("organization_…")
//	for itemResult, err := range org.Orders.Send(ctx, "order_…", &myle.OrderSendParams{To: []string{"to"}}).All() {
//		if err != nil {
//			return err
//		}
//		fmt.Println(itemResult.ID)
//	}
func (s *OrdersService) Send(ctx context.Context, orderID string, params *OrderSendParams, opts ...RequestOption) *Paginator[ItemResult] {
	path := "/organizations/" + pathEscape(s.organizationID) + "/orders/" + pathEscape(orderID) + "/send"
	op := &operation{id: "sendOrder", method: "POST", pathTemplate: "/organizations/{id}/orders/{orderId}/send", idempotent: true, retrySafe: true, contentType: "application/json"}
	return newPaginator[ItemResult](ctx, s.core, op, path, nil, bodyOf(params), false, opts)
}
